    {
      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "淡月太美 我望得出神"
        },
        {
          "id": "V1-02",
          "zh": "脚下昏暗看不清"
        },
        {
          "id": "V1-03",
          "zh": "摔倒了也 浑然不觉"
        },
        {
          "id": "V1-04",
          "zh": "远夜星光 一片模糊"
        },
        {
          "id": "V1-05",
          "zh": "想做的事 一件也找不到"
        },
        {
          "id": "V1-06",
          "zh": "假装匆忙 低头不语"
        },
        {
          "id": "V1-07",
          "zh": "跌倒之后 总被人笑"
        },
        {
          "id": "V1-08",
          "zh": "我就装作 没听见"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "淡月令我沉醉所以"
        },
        {
          "id": "V1-02",
          "zh": "连暗处脚下都看不见"
        },
        {
          "id": "V1-03",
          "zh": "一直没察觉自己已跌倒"
        },
        {
          "id": "V1-04",
          "zh": "远方夜星模糊一片"
        },
        {
          "id": "V1-05",
          "zh": "因为找不到想做的事啊"
        },
        {
          "id": "V1-06",
          "zh": "装作匆忙 仍低着头"
        },
        {
          "id": "V1-07",
          "zh": "跌倒之后被人嘲笑的模样"
        },
        {
          "id": "V1-08",
          "zh": "我就装作没有发觉"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "看淡淡的月光 我忘了脚下的路"
        },
        {
          "id": "V1-02",
          "zh": "脚下一片黑 什么都看不清"
        },
        {
          "id": "V1-03",
          "zh": "跌倒也没察觉 我还在原地发愣"
        },
        {
          "id": "V1-04",
          "zh": "远处的星光 晕开成一片雾"
        },
        {
          "id": "V1-05",
          "zh": "真正想做的事 我一件也找不到"
        },
        {
          "id": "V1-06",
          "zh": "装作匆忙 低着头不肯出声"
        },
        {
          "id": "V1-07",
          "zh": "跌倒后我听见 身后传来谁的笑声"
        },
        {
          "id": "V1-08",
          "zh": "我就装作 什么也没有听见"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "淡月令人醉"
        },
        {
          "id": "V1-02",
          "zh": "暗处脚下看不见"
        },
        {
          "id": "V1-03",
          "zh": "摔倒也未察觉"
        },
        {
          "id": "V1-04",
          "zh": "远夜星光晕染开"
        },
        {
          "id": "V1-05",
          "zh": "找不到想做的事"
        },
        {
          "id": "V1-06",
          "zh": "装作匆忙低着头"
        },
        {
          "id": "V1-07",
          "zh": "摔倒后被人嘲笑"
        },
        {
          "id": "V1-08",
          "zh": "假装没注意到"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "月光淡得醉人 脚下黑了也不管"
        },
        {
          "id": "V1-02",
          "zh": "低着头走路 脚尖也看不清"
        },
        {
          "id": "V1-03",
          "zh": "踉跄两步往前 摔了都还没发觉"
        },
        {
          "id": "V1-04",
          "zh": "远处夜星 在眼里晕成一片"
        },
        {
          "id": "V1-05",
          "zh": "想做的事情 竟然一件都找不见"
        },
        {
          "id": "V1-06",
          "zh": "假装走得很急 头一直低垂"
        },
        {
          "id": "V1-07",
          "zh": "摔了一跤之后 还有笑声悬在背后"
        },
        {
          "id": "V1-08",
          "zh": "我垂着眼 装作什么都没听"
        }
      ]
    }
  ]
}

